// LoadTextureData opens an image asset (PNG or JPEG), decodes it, and returns
// its dimensions plus the pixels packed as 0xAABBGGRR uint32 values (the
// renderer's color format). It returns primitives rather than a
// mesh.TextureData so this package does not import the mesh package (which
// already imports this one), avoiding an import cycle. Callers build the
// mesh.TextureData from the result.
func LoadTextureData(path string) (width int, height int, pixels []uint32, err error) {
	file, err := assets.OpenAsset(path)
	if err != nil {
		return 0, 0, nil, err
	}
	defer file.Close()

	img, fileFormat, err := image.Decode(file)
	if err != nil {
		return 0, 0, nil, err
	}
	if fileFormat != "png" && fileFormat != "jpeg" {
		return 0, 0, nil, fmt.Errorf("unsupported file format: %s", fileFormat)
	}

	bounds := img.Bounds()
	tw, th := bounds.Max.X, bounds.Max.Y

	meshTexture := make([]uint32, tw*th)
	for y := 0; y < th; y++ {
		for x := 0; x < tw; x++ {
			r16, g16, b16, a16 := img.At(x, y).RGBA()
			r8 := uint8(r16 >> 8)
			g8 := uint8(g16 >> 8)
			b8 := uint8(b16 >> 8)
			a8 := uint8(a16 >> 8)
			meshTexture[(y*tw)+x] = (uint32(a8) << 24) | (uint32(b8) << 16) | (uint32(g8) << 8) | uint32(r8)
		}
	}
	return tw, th, meshTexture, nil
}
